<script lang="ts">
 import {onDestroy} from 'svelte';
 import {at,demoTrack,parseTrack,parseMap,mp4Creation,frameSvg,coverage,bestAlignment,makeManualTrack,manualHasMap,serializeTrack,type ManualKey,type Track,type MapLine,type Palette,type View} from '../lib/telemetry';
 export let palette:Palette;
 export let onClose:()=>void;
 export let saveText:(name:string,content:string,mime:string)=>Promise<void>;
 export let renderVideo:(width:number,height:number,duration:number,fps:30|60,render:(t:number)=>string,progress:(n:number,total:number)=>void,cancel:()=>boolean,mode:'alpha'|'green'|'blue'|'black')=>Promise<string>;
 export let mobile=false;
 export let gps:{start:()=>Promise<void>;stop:()=>Promise<Track>;status:()=>Promise<boolean>}|undefined=undefined;
 let track=demoTrack(),roads:MapLine[]=[],start=track.points[0].t,clock=0,duration=60,offset=0;
 let url='',video:HTMLVideoElement,videoCreation:number|null=null,clockOrigin:'start'|'end'='start';
 let running=false,timer:ReturnType<typeof setInterval>|undefined,last=0;
 let orientation:'landscape'|'portrait'='landscape',corner='bottom-right',scale=1,opacity=.95,heading=true,tilt=false,radius=220,autoZoom=true,theme='dark',gauge='digital',map=true;
 let status='Percurso fictício carregado. Nenhuma localização real foi registrada.',fps:30|60=60,exporting=false,cancelled=false,recording=false;
 let stamp='',videoName='',gpsName='Percurso demonstrativo',mapName='';
 let videoReady=false;
 let exportMode:'alpha'|'green'|'blue'|'black'='alpha',panel:'sync'|'visual'|'export'='sync',gpsAnchor=0;
 let percent=0;
 let keyTime=0,keySpeed=0,keyStreet='',keyLat='',keyLon='';
 let selectedKey:number|null=null;
 $: manual=track.manualKeys!==undefined;
 $: manualKeys=track.manualKeys??[];
 $: hasManualMap=manualHasMap(track);
 $: percent=Math.round(100*coverage(track,start+offset*1000,duration));
 $: trackSeconds=track.manualKeys?(track.manualDuration??duration):(track.points[track.points.length-1].t-track.points[0].t)/1000;
 $: localStart=new Date(start+offset*1000).toLocaleString('pt-BR');
 $: view={width:orientation==='portrait'?1080:1920,height:orientation==='portrait'?1920:1080,corner,scale,opacity,heading,tilt,radius,autoZoom,theme,gauge,map,palette} as View;
 $: current=at(track,start+(clock+offset)*1000);
 $: svg=frameSvg(track,start+(clock+offset)*1000,view,roads);
 $: stamp=new Date(start).toISOString().slice(0,23)+'Z';
 $: if(gps)void gps.status().then(v=>recording=v).catch(()=>{});
 function stop(){running=false;if(timer!==undefined)clearInterval(timer);timer=undefined;video?.pause();}
 function seek(n:number){clock=Math.max(0,Math.min(duration,n));if(video&&url)video.currentTime=clock;}
 function play(){if(running){stop();return;}if(clock>=duration)seek(0);running=true;last=performance.now();if(video&&url)void video.play().catch(e=>{stop();status=String(e)});timer=setInterval(()=>{const now=performance.now();clock=video&&url?video.currentTime:Math.min(duration,clock+(now-last)/1000);last=now;if(clock>=duration||video?.ended)stop();},33);}
 function loadTrack(t:Track){stop();track=t;start=t.manualKeys?0:t.points[0].t;offset=0;clock=0;selectedKey=null;if(t.manualKeys){if(!url)duration=t.manualDuration??60;panel='sync';}else if(url)autoAlign();else duration=(t.points[t.points.length-1].t-start)/1000;seek(0);}
 async function openTrack(e:Event){const input=e.currentTarget as HTMLInputElement;const f=input.files?.[0];if(!f)return;if(track.manualKeys?.length&&!confirm('Substituir o projeto manual aberto? Salve-o antes, se necessário.')){input.value='';return;}try{if(f.size>60e6)throw Error('Arquivo GPS acima de 60 MB.');loadTrack(parseTrack(await f.text(),f.name));gpsName=f.name;if(track.manualKeys)status='Projeto manual importado. Selecione o vídeo correspondente.';else if(url)autoAlign();else status='GPS importado. Agora selecione o vídeo.';}catch(err){status=String(err);}finally{input.value='';}}
 async function openMap(e:Event){const input=e.currentTarget as HTMLInputElement;const f=input.files?.[0];if(!f)return;try{if(f.size>60e6)throw Error('Mapa acima de 60 MB.');roads=parseMap(await f.text());mapName=f.name;status=roads.length+' vias importadas. Use cartografia licenciada e preserve a atribuição.';}catch(err){status=String(err);}finally{input.value='';}}
 async function openVideo(e:Event){const f=(e.currentTarget as HTMLInputElement).files?.[0];if(!f)return;stop();if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(f);videoName=f.name;videoReady=false;videoCreation=null;clock=0;try{videoCreation=await mp4Creation(f);autoAlign();}catch(err){status=String(err);}}
 function loadedVideo(){if(!video||!Number.isFinite(video.duration))return;duration=video.duration;videoReady=true;orientation=video.videoHeight>video.videoWidth?'portrait':'landscape';autoAlign();}
 function autoAlign(){if(track.manualKeys){start=0;offset=0;status='Telemetria manual vinculada ao tempo do vídeo.';return;}const result=bestAlignment(track,videoCreation,duration);start=result.start;clockOrigin=result.origin;offset=0;const p=Math.round(coverage(track,start,duration)*100);status=result.manual?(track.demo?'Demonstração alinhada ao início do GPS fictício.':'Sem horário confiável: início da sessão usado como referência manual.'):(p===0?'Sem correspondência de horários. Ajuste o ponto GPS manualmente.':'Horários alinhados. Cobertura aproximada '+p+'%. Confira a reprodução.');}
 function anchor(){stop();start=track.points[0].t+(Math.max(0,Math.min(trackSeconds,gpsAnchor||0))-clock)*1000;offset=0;status='Quadro atual alinhado ao ponto GPS escolhido.';}
 function align(){if(videoCreation!==null)start=videoCreation-(clockOrigin==='end'?duration*1000:0);}
 function setStamp(v:string){const n=Date.parse(v);if(Number.isFinite(n))start=n;else status='Horário inválido. Informe ISO 8601 com fuso horário.';}
 function startManual(){if(track.manualKeys){panel='sync';return;}if(!videoReady){status='Importe primeiro o vídeo original para criar telemetria manual.';return;}if(!track.demo&&!confirm('Substituir a sessão atual pela edição manual? Salve a sessão GPS antes, se necessário.'))return;stop();track=makeManualTrack([],duration);start=0;offset=0;gpsName='Telemetria manual';selectedKey=null;keyTime=clock;keySpeed=0;keyStreet='';keyLat='';keyLon='';panel='sync';status='Posicione o vídeo, informe a velocidade e adicione um ponto.';}
 function captureTime(){stop();selectedKey=null;keyTime=Math.round(clock*1000)/1000;const exact=track.manualKeys?.find(k=>k.time===keyTime);if(exact){editKey(exact);return;}const current=at(track,keyTime*1000);if(current?.speed!==undefined)keySpeed=Math.round(current.speed*36)/10;if(current?.street)keyStreet=current.street;keyLat='';keyLon='';}
 function editKey(k:ManualKey){stop();seek(k.time);selectedKey=k.time;keyTime=k.time;keySpeed=k.speedKmh;keyStreet=k.street;keyLat=k.lat===undefined?'':String(k.lat);keyLon=k.lon===undefined?'':String(k.lon);}
 function saveKey(){if(!track.manualKeys)return;try{if(!Number.isFinite(keyTime)||keyTime<0||keyTime>duration+.001||!Number.isFinite(keySpeed))throw Error('Informe um instante dentro do vídeo e uma velocidade válida.');const k:ManualKey={time:Math.round(Math.min(duration,keyTime)*1000)/1000,speedKmh:keySpeed,street:keyStreet};if(keyLat.trim()||keyLon.trim()){if(!keyLat.trim()||!keyLon.trim())throw Error('Preencha as duas coordenadas.');k.lat=Number(keyLat.replace(',','.'));k.lon=Number(keyLon.replace(',','.'));}const others=track.manualKeys.filter(x=>x.time!==selectedKey&&x.time!==k.time);track=makeManualTrack([...others,k],duration);selectedKey=k.time;seek(k.time);status='Ponto manual salvo.';}catch(err){status=String(err);}}
 function deleteKey(time:number){if(!track.manualKeys)return;track=makeManualTrack(track.manualKeys.filter(k=>k.time!==time),duration);selectedKey=null;status='Ponto removido.';}
 function demo(){if(track.manualKeys?.length&&!confirm('Trocar para a demonstração? Salve o projeto manual antes, se necessário.'))return;if(url)URL.revokeObjectURL(url);url='';videoReady=false;videoName='';roads=[];mapName='';gpsName='Percurso demonstrativo';loadTrack(demoTrack());status='Percurso fictício (não representa uma viagem real).';}
 async function saveGps(){try{await saveText(track.manualKeys?'telemetria_manual.rdvgps':'telemetria.rdvgps',serializeTrack(track,duration),'application/json');status='Sessão disponibilizada.';}catch(err){status=String(err);}}
 async function saveCsv(){try{await saveText('telemetria.csv','time,lat,lon,speed_mps,bearing\n'+track.points.map(p=>[new Date(p.t).toISOString(),p.lat,p.lon,p.speed??'',p.bearing??''].join(',')).join('\n'),'text/csv');}catch(err){status=String(err);}}
 async function saveGpx(){try{const xml='<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="RDV Bus Studio" xmlns="http://www.topografix.com/GPX/1/1" xmlns:rdv="urn:rdv:telemetry"><trk><trkseg>'+track.points.map(p=>'<trkpt lat="'+p.lat+'" lon="'+p.lon+'"><time>'+new Date(p.t).toISOString()+'</time><extensions>'+(p.speed===undefined?'':'<rdv:speed>'+p.speed+'</rdv:speed>')+'</extensions></trkpt>').join('')+'</trkseg></trk></gpx>';await saveText('telemetria.gpx',xml,'application/gpx+xml');}catch(err){status=String(err);}}
 async function recover(){if(!gps||recording)return;if(track.manualKeys?.length&&!confirm('Recuperar GPS e substituir projeto manual?'))return;try{loadTrack(await gps.stop());gpsName='Última sessão GPS';status='Última sessão recuperada; salve antes de iniciar outra.';}catch(err){status=String(err);}}
 async function record(){if(!gps)return;try{if(recording){const t=await gps.stop();recording=false;loadTrack(t);gpsName='Sessão GPS gravada';status='Registro encerrado; salve a sessão GPS.';}else{if(track.manualKeys?.length&&!confirm('Iniciar novo registro GPS? Salve o projeto manual antes de substituir os dados.'))return;await gps.start();recording=true;status='Registro iniciado. Pode abrir a câmera Samsung.';}}catch(err){recording=await gps.status().catch(()=>false);status=String(err);}}
 async function exportClip(){stop();if(exporting)return;if(track.manualKeys&&track.manualKeys.length<2){status='Adicione pelo menos dois pontos manuais antes de exportar.';return;}if(url&&!videoReady){status='Aguarde a leitura do vídeo.';return;}if(mobile&&Math.ceil(duration*fps)>7200){status='Limite Android: 7.200 quadros por exportação. Use 30 FPS ou exporte no Desktop.';return;}const tr=track,rs=roads,v={...view,palette:{...palette}},base=start+offset*1000,d=duration;exporting=true;cancelled=false;try{status=await renderVideo(v.width,v.height,d,fps,t=>frameSvg(tr,base+t*1000,v,rs),(n,total)=>status='Renderizando '+n+'/'+total,()=>cancelled,exportMode);}catch(err){status=String(err);}finally{exporting=false;}}
 onDestroy(()=>{stop();if(url)URL.revokeObjectURL(url);});
</script>
<section class="gps-shell" class:mobile aria-label="Navigator GPS">
 <header><div><strong>RDV Bus Studio · Navigator</strong><small>Telemetria sincronizada · Alpha</small></div><button disabled={exporting} on:click={onClose}>Voltar ao Studio</button></header>
 <div class="gps-actions"><button disabled={exporting} on:click={demo}>Percurso demonstrativo</button><button class:gold={manual} disabled={exporting||recording||(!videoReady&&!manual)} on:click={startManual}>Telemetria manual</button>{#if gps}<button disabled={exporting} on:click={()=>void record()}>{recording?'Encerrar GPS':'Iniciar GPS em segundo plano'}</button>{#if !recording}<button disabled={exporting} on:click={()=>void recover()}>Recuperar última sessão</button>{/if}{/if}
 <div class="gps-files"><label class="gps-file"><span>1 · Importar vídeo original</span><small>{videoName||"Selecionar MP4"}</small><input disabled={exporting} type="file" accept="video/mp4,video/*" on:change={openVideo}/></label><label class="gps-file"><span>2 · Importar GPS</span><small>{gpsName}</small><input disabled={exporting} type="file" accept=".gpx,.csv,.json,.rdvgps" on:change={openTrack}/></label><label class="gps-file"><span>Mapa de ruas (opcional)</span><small>{mapName||"Selecionar GeoJSON"}</small><input disabled={exporting} type="file" accept=".geojson,.json" on:change={openMap}/></label></div></div>
 <div class="gps-content">
 <div><div class="gps-preview" style:aspect-ratio={orientation==='portrait'?'9/16':'16/9'}>{#if url}<video bind:this={video} src={url} on:loadedmetadata={loadedVideo} playsinline preload="metadata" on:error={()=>{videoReady=false;status="Não foi possível decodificar o vídeo selecionado.";}}></video>{:else}<div class="gps-empty"> {track.demo?'MODO DEMONSTRAÇÃO':'PRÉVIA TRANSPARENTE'} </div>{/if}<div class="gps-overlay">{@html svg}</div></div>
 <div class="gps-timeline"><button on:click={play} disabled={exporting}>{running?'Pausar':'Reproduzir'}</button><input aria-label="Tempo do vídeo" type="range" min="0" max={duration} step=".0333333" value={clock} on:input={e=>{stop();seek(Number(e.currentTarget.value));}}/><span>{clock.toFixed(2)} / {duration.toFixed(2)} s</span></div>
 <p>{current?.speed===undefined?'GPS / velocidade indisponível':Math.round(current.speed*3.6)+' km/h'} · {manual?manualKeys.length:track.points.length} pontos {manual?'manuais (estimados)':track.demo?'fictícios':''}</p></div>
 <div class="gps-controls"><div class="gps-tabs">{#each ["sync","visual","export"] as item,i}<button class:active={panel===item} disabled={exporting} on:click={()=>panel=item as typeof panel}>{[manual?"Pontos":"Sincronizar","Visual","Exportar"][i]}</button>{/each}</div>
 {#if panel==="sync"&&manual}<h3>Telemetria manual · pontos-chave</h3><small>Valores estimados, não medidos pelo GPS. Fora dos pontos definidos, a velocidade fica indisponível. Para cobrir todo o vídeo, adicione pontos no início e no final.</small><button on:click={captureTime}>Usar instante atual ({clock.toFixed(2)} s)</button><label>Tempo do vídeo (s)<input type="number" min="0" max={duration} step=".001" bind:value={keyTime}/></label><label>Velocidade (km/h)<input type="number" min="0" max="300" step="1" bind:value={keySpeed}/></label><label>Rua / avenida<input type="text" maxlength="120" bind:value={keyStreet}/></label><details><summary>Coordenadas opcionais</summary><label>Latitude<input placeholder="-15.60" bind:value={keyLat}/></label><label>Longitude<input placeholder="-56.10" bind:value={keyLon}/></label><small>O minimapa exige pelo menos dois pontos e coordenadas em todos os pontos. Trajeto interpolado, não navegação por ruas.</small></details><button class="gold" on:click={saveKey}>{selectedKey===null?"Adicionar ponto":"Atualizar ponto"}</button><div class="gps-key-list">{#each manualKeys as k (k.time)}<div class="gps-key"><button on:click={()=>editKey(k)}>{k.time.toFixed(2)} s · {k.speedKmh} km/h{#if k.street}<small>{k.street}</small>{/if}</button><button aria-label={"Remover ponto em "+k.time+" segundos"} on:click={()=>deleteKey(k.time)}>✕</button></div>{/each}</div><button on:click={()=>void saveGps()}>Salvar projeto manual (.rdvgps)</button>{:else if panel==="sync"}<h3>Sincronização</h3><button class="gold" disabled={exporting||!videoReady} on:click={autoAlign}>Sincronizar automaticamente</button><p>Início: {localStart} · Cobertura GPS: <strong>{percent}%</strong>{track.demo?" · SIMULAÇÃO":""}</p><progress max="100" value={percent}></progress><label>Horário inicial (UTC / ISO 8601)<input value={stamp} on:change={e=>setStamp(e.currentTarget.value)}/></label>
 {#if videoCreation!==null}<label>Horário do MP4<select bind:value={clockOrigin} on:change={align}><option value="start">Início</option><option value="end">Final</option></select></label>{/if}
 <label>Ajuste GPS (segundos)<input type="number" step=".1" bind:value={offset}/></label>
 <div class="gps-nudge"><button on:click={()=>offset-=1}>−1 s</button><button on:click={()=>offset-=.1}>−0,1 s</button><button on:click={()=>offset=0}>Zerar</button><button on:click={()=>offset+=.1}>+0,1 s</button><button on:click={()=>offset+=1}>+1 s</button></div><label>Ponto na sessão GPS (s)<input type="number" min="0" max={trackSeconds} step=".1" bind:value={gpsAnchor}/></label><button on:click={anchor}>Alinhar quadro atual ao ponto GPS</button><small>Valores positivos adiantam o GPS; negativos atrasam. A cobertura não garante precisão real.</small>{:else if panel==="visual"}<h3>Visualização</h3><label>Formato<select bind:value={orientation}><option value="landscape">16:9</option><option value="portrait">9:16</option></select></label>
 <label>Canto<select bind:value={corner}><option value="top-left">Superior esquerdo</option><option value="top-right">Superior direito</option><option value="bottom-left">Inferior esquerdo</option><option value="bottom-right">Inferior direito</option></select></label>
 <label>Escala<input type="range" min=".4" max="2.5" step=".05" bind:value={scale}/></label><label>Opacidade<input type="range" min=".15" max="1" step=".05" bind:value={opacity}/></label>
 <label>Velocímetro<select bind:value={gauge}><option value="digital">Digital</option><option value="analog">Digital + analógico</option></select></label>
 <label><input type="checkbox" bind:checked={map} disabled={manual&&!hasManualMap}/> Mostrar minimapa</label><label><input type="checkbox" bind:checked={heading}/> Girar na direção do veículo</label><label><input type="checkbox" bind:checked={tilt}/> Vista inclinada experimental (2,5D)</label><label><input type="checkbox" bind:checked={autoZoom}/> Zoom conforme a velocidade</label>
 <label>Raio do mapa (m)<input type="range" min="70" max="1200" step="10" bind:value={radius}/></label><label>Tema<select bind:value={theme}><option value="dark">Escuro</option><option value="light">Claro</option></select></label>
 {:else}<h3>Exportação</h3><label>Formato de saída<select bind:value={exportMode}><option value="green">MP4 · Chroma Key verde</option><option value="blue">MP4 · Chroma Key azul</option><option value="black">MP4 · fundo preto</option><option value="alpha">MOV · QuickTime Animation (alfa)</option></select></label><small>Exporta somente a sobreposição, com a duração do vídeo original. No Kdenlive, coloque acima do vídeo no mesmo instante e aplique Chroma Key ao MP4.</small><label>FPS<select bind:value={fps}><option value={30}>30 FPS</option><option value={60}>60 FPS</option></select></label>
 <button disabled={exporting} on:click={()=>void saveText('navigator.svg',svg,'image/svg+xml')}>Salvar quadro SVG</button>
 <button disabled={exporting} class="gold" on:click={()=>void exportClip()}>{exportMode==='alpha'?'Gerar MOV transparente':'Gerar MP4 de telemetria'}</button>{#if exporting}<button on:click={()=>cancelled=true}>Cancelar exportação</button>{/if}
 <div class="gps-actions"><button disabled={exporting} on:click={()=>void saveGps()}>RDVGPS</button>{#if !manual}<button disabled={exporting} on:click={()=>void saveCsv()}>CSV</button><button disabled={exporting} on:click={()=>void saveGpx()}>GPX</button>{/if}</div>
 {/if}</div></div><p class="gps-status" role="status">{status}</p><small>{manual?"Dados manuais estimados.":"Sem cartografia importada, dados reais mostram apenas o traçado GPS."} Ruas automáticas e mapa 3D real ainda não disponíveis.</small>
</section>
<style>
.gps-shell{position:fixed;inset:0;z-index:300;background:#160f20;color:#f6f0fd;overflow:auto;padding:16px;box-sizing:border-box;font:14px system-ui,sans-serif}
.gps-shell header{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:12px}.gps-shell strong{font-size:19px;color:#e2ba5a}.gps-shell small{display:block;color:#bda4d9;margin:6px 0}.gps-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:10px 0}.gps-shell button,.gps-shell input,.gps-shell select{font:inherit;color:inherit;background:#2c1e3c;border:1px solid #69468a;border-radius:6px;padding:8px;min-width:0;max-width:100%;box-sizing:border-box}.gps-shell button:disabled{opacity:.5}.gps-shell label{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.gps-content{display:grid;grid-template-columns:minmax(0,2fr) minmax(250px,1fr);gap:16px}.gps-preview{position:relative;background:#101015;max-height:70vh;margin:auto;width:100%;overflow:hidden}.gps-preview video,.gps-overlay,.gps-empty{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.gps-overlay{pointer-events:none}.gps-overlay :global(svg){width:100%;height:100%}.gps-empty{display:grid;place-items:center;color:#a294b2;background:repeating-conic-gradient(#24202c 0% 25%,#1c1823 0% 50%) 50%/20px 20px}.gps-timeline{display:flex;align-items:center;gap:8px;margin:8px 0;flex-wrap:wrap}.gps-timeline input{flex:1}.gps-controls{display:grid;gap:8px;align-content:start}.gps-controls h3{margin:8px 0 2px;color:#e2ba5a}.gps-controls label{justify-content:space-between}.gps-controls input:not([type=checkbox]),.gps-controls select{max-width:65%}.gps-shell p{color:#d4c4e7;overflow-wrap:anywhere}@media(max-width:750px){.gps-content{grid-template-columns:1fr}.gps-shell{padding:10px}.gps-preview{max-height:55vh}}
.gps-shell.mobile{padding-top:calc(12px + max(28px,var(--safe-area-inset-top,env(safe-area-inset-top,0px))));padding-bottom:calc(16px + max(24px,var(--safe-area-inset-bottom,env(safe-area-inset-bottom,0px))));padding-left:calc(12px + env(safe-area-inset-left,0px));padding-right:calc(12px + env(safe-area-inset-right,0px));}
.gps-shell header{align-items:flex-start}.gps-shell header strong{font-size:17px}.gps-shell header button{flex-shrink:0;font-size:12px}.gps-files{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));width:100%;gap:8px}.gps-shell .gps-file{position:relative;display:flex;flex-direction:column;align-items:flex-start;min-width:0;border:1px solid #69468a;border-radius:8px;padding:10px;background:#2c1e3c;overflow:hidden}.gps-file span{font-weight:700}.gps-file small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}.gps-file input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.gps-file:focus-within{outline:2px solid #e2ba5a}.gps-tabs,.gps-nudge{display:flex;gap:5px;flex-wrap:wrap}.gps-tabs button{flex:1}.gps-tabs button.active,.gps-shell button.gold{background:#e2ba5a;color:#21142e;font-weight:700}.gps-shell input[type=range],.gps-shell progress{accent-color:#e2ba5a}.gps-shell progress{width:100%}.gps-status{padding:10px;border:1px solid #69468a;border-radius:8px;background:#24172f}.gps-preview{max-height:none}.gps-preview:has(video){background:#000}
.gps-key-list{display:grid;gap:6px;max-height:270px;overflow:auto}.gps-key{display:flex;gap:6px}.gps-key button:first-child{flex:1;text-align:left}.gps-key small{white-space:normal;overflow-wrap:anywhere}.gps-controls details{border:1px solid #69468a;border-radius:8px;padding:10px}.gps-controls details label{margin-top:8px}</style>